import type { ArtemisHeroContent } from "../content";
const DEFAULT = {
    badge: "A few extra minds on your team",
    headline: "Your new",
    headlineAccent: "AI teammates",
    subhead: "Give each teammate a role, share what needs doing, and let them take it from there. They bring the finished work back to you.",
    cta: { label: "Meet your team" },
    secondaryCta: { label: "See their work" },
    note: "A little more headspace. A lot more possibility.",
