export default function HeroSectionsAiTeammates({ content }: { content?: Partial<ArtemisHeroContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
