    const conversationInView = useInView(conversationRef, { amount: 0.5 });
    const visualRef = useRef<HTMLDivElement>(null);
    const visualInView = useInView(visualRef, { amount: 0.1 });
    const person = team[selected];
    const phase = elapsed < 1800 ? 0 : elapsed < 3600 ? 1 : elapsed < 5800 ? 2 : 3;
    const complete = phase === 3;
    const status = complete ? "Ready for review" : playing ? "Working on it" : "Paused";
    const filtered = teamKeys.filter(key => `${team[key].name} ${team[key].role} ${team[key].idle}`.toLowerCase().includes(query.trim().toLowerCase()));
    useEffect(() => { if (!playing || complete || !conversationInView)
        return; const timer = window.setTimeout(() => setElapsed([1800, 3600, 5800][phase]), [1800, 1800, 2200][phase]); return () => window.clearTimeout(timer); }, [playing, complete, phase, run, conversationInView]);
    useEffect(() => { if (complete)
        setPlaying(false); }, [complete]);
    useEffect(() => { if (reduce) {
        setElapsed(5800);
        setPlaying(false);
    } }, [reduce]);
    useEffect(() => { const node = conversationRef.current; if (node)
        node.scrollTop = node.scrollHeight; }, [phase, run]);
    const replay = () => { setElapsed(reduce ? 5800 : 0); setPlaying(!reduce); setRun(n => n + 1); };
    const choose = (key: TeammateKey) => { setSelected(key); replay(); };
    const rise = (delay: number) => ({ initial: reduce ? false as const : { opacity: 0, y: 10 }, animate: { opacity: 1, y: 0 }, transition: reduce ? { duration: 0 } : { duration: 0.5, delay, ease: ARTEMIS_EASE_OUT } });
    const word = (index: number) => artemisWordMotion(index, reduce === true, { stagger: 0, delay: [0, .055, .12, .175][index] ?? .175 + (index - 3) * .055, blur: 4, yOffset: 12 });
    const lines = [copy.headline, accent].map(line => (line ?? "").split(/\s+/).filter(Boolean)).filter(words => words.length > 0);
    return (<>
