              <motion.p className="art:inline-flex art:items-center art:gap-2 art:text-xs art:text-muted-foreground" {...rise(0)}>
                <span className="art:grid art:size-7 art:place-items-center art:rounded-full art:border art:border-border">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-message-circle art:size-3.5" aria-hidden="true">
                    <path d="M2.992 16.342a2 2 0 0 1 .094 1.167l-1.065 3.29a1 1 0 0 0 1.236 1.168l3.413-.998a2 2 0 0 1 1.099.092 10 10 0 1 0-4.777-4.719"/>
                  </svg>
                </span>
                {copy.badge}
              </motion.p>
              <h1 id={`${id}-title`} className="art:text-balance art:font-sans art:font-medium art:text-5xl art:@min-[768px]/artemis:text-6xl art:leading-[0.94] art:tracking-[-0.055em] art:mt-6">
                {lines.map((words, line) => {
                    const first = lines.slice(0, line).reduce((count, previous) => count + previous.length, 0);
                    return <span key={line} className={line ? "art:mt-2 art:block" : "art:block"}>
                  <span className="art:block">
                    {words.map((text, index) => <motion.span key={index} className="art:inline-block art:will-change-transform" {...word(first + index)}>
                      {text}
                      {index < words.length - 1 ? <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                        {"\u00A0"}
                      </span> : null}
                    </motion.span>)}
                  </span>
                </span>;
                })}
              </h1>
              <motion.p className="art:mx-auto art:mt-6 art:max-w-md art:text-pretty art:text-sm art:leading-7 art:text-muted-foreground art:@min-[640px]/artemis:text-base art:@min-[1024px]/artemis:mx-0" {...rise(0.12)}>
