                  {copy.cta.label}
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-down art:size-4" aria-hidden="true">
                    <path d="M12 5v14"/>
                    <path d="m19 12-7 7-7-7"/>
                  </svg>
                </motion.button>
                <motion.button whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => setBriefOpen(true)} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:relative art:after:absolute art:after:-inset-y-0.5 art:after:inset-x-0 art:rounded-full" tabIndex={0}>
                  {copy.secondaryCta.label}
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true">
                    <path d="M7 7h10v10"/>
                    <path d="M7 17 17 7"/>
                  </svg>
                </motion.button>
              </motion.div>
              <motion.p className="art:mt-6 art:text-xs art:text-muted-foreground" {...rise(0.24)}>
                {copy.note}
              </motion.p>
            </div>
            <div ref={visualRef} className="art:relative art:isolate art:min-w-0">
              <div aria-hidden="true" className="art:pointer-events-none art:absolute art:-inset-x-8 art:-inset-y-4 art:-z-10 art:[mask-image:radial-gradient(ellipse_at_center,black_25%,transparent_70%)] art:@min-[640px]/artemis:-inset-x-12 art:@min-[640px]/artemis:-inset-y-8">
                <TeamShader active={visualInView}/>
              </div>
              <div className="art:absolute art:inset-x-3 art:top-5 art:z-10 art:flex art:items-center art:@min-[640px]/artemis:inset-x-6">
                <p className="art:flex art:items-center art:gap-2 art:rounded-full art:border art:border-border art:bg-background/90 art:px-3 art:py-2 art:text-xs">
                  <Avatar kind="assistant" className="art:shrink-0 art:size-5"/>
                  {"Assistant"}
                  {" \u00B7 Your AI team"}
