        <motion.span className="art:flex art:flex-col art:items-center" initial={{ scale: 1 }} animate={{ scale: reduce ? 1 : selected === key ? 1.04 : 0.94 }} transition={{ duration: 0.35, ease: ARTEMIS_EASE_OUT }}>
