                    {"YOUR TEAM"}
                  </p>
                </div>
                <nav aria-label="Demo teammates" className="art:flex art:gap-1 art:overflow-x-auto art:p-3 art:@min-[768px]/artemis:flex-col art:@min-[768px]/artemis:overflow-visible art:@min-[768px]/artemis:pt-0">
        {filtered.map(key => <motion.button key={key} type="button" className="art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:shrink-0 art:text-left art:rounded-full" aria-label={`Open ${team[key].name} conversation`} aria-pressed={selected === key} tabIndex={0} onClick={() => choose(key)} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS}>
        <span className={`art:flex art:items-center art:gap-2 art:rounded-2xl art:border art:px-2.5 art:py-2.5 art:@min-[768px]/artemis:gap-2.5 art:@min-[768px]/artemis:px-3 art:@min-[768px]/artemis:py-3 ${selected === key ? "art:border-border" : "art:border-transparent"}`}>
        <Avatar kind={key} className="art:shrink-0 art:size-6 art:@min-[768px]/artemis:size-9"/><span className="art:min-w-0 art:flex-1"><span className="art:flex art:items-center art:justify-between art:gap-2 art:text-xs art:font-medium art:@min-[768px]/artemis:text-sm">{team[key].name}{selected === key ? <span aria-hidden="true" className="art:hidden art:size-1.5 art:rounded-full art:bg-foreground art:@min-[768px]/artemis:block"/> : null}</span><span className="art:mt-1 art:hidden art:truncate art:text-xs art:text-muted-foreground art:@min-[768px]/artemis:block">{team[key].role}</span><span className="art:mt-1 art:hidden art:truncate art:text-xs art:text-muted-foreground art:@min-[768px]/artemis:block">{selected === key ? status : team[key].idle}</span></span>
        </span></motion.button>)}
    {filtered.length === 0 ? <p className="art:px-2 art:py-4 art:text-xs art:text-muted-foreground">No matching teammates.</p> : null}
    </nav>
                <div className="art:mx-5 art:mt-auto art:hidden art:items-center art:gap-2.5 art:border-border art:border-t art:py-5 art:@min-[768px]/artemis:flex">
                  <span className="art:grid art:size-8 art:place-items-center art:rounded-full art:border art:border-border art:text-xs art:font-medium">
                    {"JD"}
                  </span>
                  <div>
                    <p className="art:text-xs art:font-medium">
                      {"Casey Reed"}
                    </p>
                    <p className="art:mt-1 art:text-xs art:text-muted-foreground">
                      {"You and your team"}
                    </p>
                  </div>
                </div>
